// Simulates one CO2 / temperature / humidity sensor per classroom.
// In the real deployment an ESP32 + Sensirion SCD41 publishes the same JSON
// to the same MQTT topic, so nothing after the broker has to change.
//
// The scenario is accelerated for the demo: CO2 rises while people are in
// the room; at 1500 ppm someone opens the window and CO2 falls back to 600 ppm.

const ROOMS = [
    { id: 'C21',  rise: 25 },   // average ppm increase per tick (10 s)
    { id: 'E101', rise: 35 },   // big lecture hall -> fastest rise
    { id: 'D105', rise: 15 },
];
const WINDOW_OPEN_AT  = 1500;   // ppm
const WINDOW_CLOSE_AT = 600;    // ppm

const state = context.get('state') || {};

for (const room of ROOMS) {
    const s = state[room.id] || {
        co2: 450 + Math.round(Math.random() * 400),
        temp: 21.5 + Math.random(),
        hum: 40 + Math.random() * 10,
        windowOpen: false,
    };

    if (s.windowOpen) {
        s.co2 -= 60 + Math.round(Math.random() * 20);
        s.temp -= 0.1;
        if (s.co2 <= WINDOW_CLOSE_AT) s.windowOpen = false;
    } else {
        s.co2 += Math.round(room.rise * (0.5 + Math.random()));
        s.temp += 0.03 + (Math.random() - 0.5) * 0.05;
        if (s.co2 >= WINDOW_OPEN_AT) s.windowOpen = true;
    }

    s.co2  = Math.max(420, s.co2);
    s.temp = Math.min(26, Math.max(19, s.temp));
    s.hum  = Math.min(65, Math.max(30, s.hum + (Math.random() - 0.5) * 0.6));
    state[room.id] = s;

    node.send({
        topic: `classroom/${room.id}/telemetry`,
        payload: {
            room: room.id,
            co2: s.co2,
            temp: +s.temp.toFixed(1),
            hum: +s.hum.toFixed(1),
        },
    });
}

context.set('state', state);
return null;

// Validates one sensor message and classifies the air quality.
//   CO2 < 1000 ppm      -> good
//   CO2 1000-1400 ppm   -> warning  (ventilation recommended)
//   CO2 > 1400 ppm      -> critical (ventilate now)

const room = msg.topic.split('/')[1];
const p = msg.payload;

const valid = p && typeof p === 'object' &&
    [p.co2, p.temp, p.hum].every(v => typeof v === 'number' && Number.isFinite(v));
if (!valid) {
    node.warn(`Invalid payload on ${msg.topic}: ${JSON.stringify(p)}`);
    return null;
}

const status = p.co2 < 1000 ? 'good' : p.co2 <= 1400 ? 'warning' : 'critical';

const colour = { good: 'green', warning: 'yellow', critical: 'red' }[status];
node.status({ fill: colour, shape: 'dot', text: `${room}: ${p.co2} ppm (${status})` });

msg.payload.status = status;
msg.params = [room, Math.round(p.co2), p.temp, p.hum, status];
return msg;
